def read_csv(path):
    with path.open(encoding="utf-8-sig", newline="") as f:
        return list(csv.DictReader(f))

def dt(value):
    if not value: return None
    try: return datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError: return None

def norm(x): return str(x).strip().casefold() if x is not None else ""
def nested_records(value, path=()):
    if isinstance(value, dict):
        if any(k in value for k in ("resource_id", "id")):
            yield path, value
        for k,v in value.items(): yield from nested_records(v, path+(str(k),))
    elif isinstance(value, list):
        for v in value: yield from nested_records(v,path)

def sys_for(path, rec):
    hint=" ".join(path).lower()
    keys=" ".join(map(str,rec.keys())).lower()
    pairs=[("account", "account_service"),("profile", "account_service"),("tombstone", "identity_service"),("deleted_customer", "identity_service"),("security", "security_service"),("audit", "security_service"),("search", "search_service"),("index", "search_service"),("analytics", "analytics_platform"),("support", "support_platform"),("ticket", "support_platform"),("connector", "integration_service"),("integration", "integration_service"),("backup", "backup_service"),("restore", "backup_service"),("export", "export_service"),("marketing", "marketing_platform"),("email_delivery", "notification_service")]
    for token,sys in pairs:
        if token in hint or token in keys:return sys
    return ""

def ids_for_case(case, identities, audits):
    em=norm(case['email']); users=set(); vals={em}
    for u in identities:
        if norm(u.get('email'))==em:
            users.add(u['user_id'])
            for k in ('email','name','phone','email_hash'):
                if u.get(k): vals.add(norm(u[k]))
    for a in audits:
        if norm(a.get('field_name'))=='email' and norm(a.get('new_value'))==em: users.add(a['user_id'])
    for u in users:
        for a in audits:
            if a.get('user_id')==u:
                if a.get('field_name','').lower() in ('email','name','phone','email_hash'):
                    for k in ('old_value','new_value'):
                        if a.get(k): vals.add(norm(a[k]))
        for row in identities:
            if row['user_id']==u:
                for k in ('email','name','phone','email_hash'):
                    if row.get(k): vals.add(norm(row[k]))
