def evidence_records(manifest, cutoff):
    result=[]
    for m in manifest:
        cap=dt(m['captured_at'])
        if not cap or cap>cutoff: continue
        p=DATA/m['file_path']
        if not p.exists(): continue
        fid=m['file_id']; suffix=p.suffix.lower()
        if suffix=='.json':
            try: data=json.loads(p.read_text(encoding='utf-8-sig'))
            except Exception: continue
            for path,rec in nested_records(data):
                sys=sys_for(path,rec)
                if not sys: continue
                result.append((fid,sys,rec,path))
        elif suffix=='.sql':
            con=sqlite3.connect(':memory:')
            try:
                con.executescript(p.read_text(encoding='utf-8-sig'))
                for table, in con.execute("select name from sqlite_master where type='table'"):
                    cols=[x[1] for x in con.execute(f'pragma table_info("{table}")')]
                    mapping={'customer_profiles':'account_service','customer_search_documents':'search_service','customer_analytics_profiles':'analytics_platform','support_records':'support_platform','customer_exports':'export_service','connector_subscriptions':'integration_service','backup_restore_entries':'backup_service','security_audit_records':'security_service','deleted_customer_references':'identity_service'}
                    sys=mapping.get(table)
                    if not sys: continue
                    for row in con.execute(f'select * from "{table}"'):
                        result.append((fid,sys,dict(zip(cols,row)),(table,)))
            except Exception: pass
