def classify(sys, rec, path, users, ids):
    raw={norm(v) for v in rec.values() if isinstance(v,(str,int,float)) and v is not None}
    raw.update(norm(k)+"="+norm(v) for k,v in rec.items() if isinstance(v,(str,int,float)) and v is not None)
    matched=bool(raw & ids) or any(any(u and u in x for x in raw) for u in users)
    # SQL/log records often identify a subject via key/value phrases.
    if '_line' in rec:
        line=norm(rec['_line']); matched=any(v and v in line for v in ids) or any(u in line for u in users)
