        if not sys:
            for k,v in [('account','account_service'),('search','search_service'),('analytics','analytics_platform'),('support','support_platform'),('backup','backup_service'),('integration','integration_service'),('security','security_service')]:
                if k in low:sys=v;break
        if not sys:return None
        if '404' in low or 'rows=0' in low: return (sys,rid,'absent')
