    if sys=='analytics_platform':return (sys,rid,'exposed' if exposed else 'anonymized')
    if sys=='integration_service':return (sys,rid,'active' if rec.get('enabled') in (1,'1',True) or norm(rec.get('enabled'))=='true' else 'disabled')
