    return {'step_no':0,'phase':phase,'system_id':sys,'resource_id':rid,'operation':op,'state':state,'evidence_id':eid}

def deletion_request(text):
    t=norm(text)
    if any(x in t for x in ('export my data','access my data','correct my','update my','opt out','unsubscribe','marketing only','do not delete','not a deletion')):return False
    return any(x in t for x in ('delet','eras','remove my account','close my account','purge my','right to be forgotten','borrar','eliminar','supprimer','löschen','hapus','apagar'))

